def solve(g):
    n=len(g); m=len(set(r[0] for r in g if r[0]])
    # find row indices of each distinct nonzero color
    idx={}
    for i,r in enumerate(g):
        c=r[0]
        if c: idx.setdefault(c,[]).append(i)
    mp={}
    rows_of=[i for i,c in []]  # placeholder
    for c in range(10):
        pass
    # assign residue: for each color, take its row mod m; but multiple colors could share residue—pick the one present. Better: build directly from colors present:
    bands=[]
    for i,r in enumerate(g):
        c=r[0]
        if c: bands.append((i,c))
